#!/usr/bin/env python3
"""Ingest shops from the tools API → util/autogenerated/shops.py.

API shop detail provides id, name, soldItems, onlyPurchaseSellingListItems.
The legacy shops.py has richer per-item data (stock, price, currency, type)
that this API doesn't yet expose — those still need the wiki scraper.
This ingest captures the API structure verbatim for forward use.
"""
from __future__ import annotations
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent.parent))
from util.scrapers.tools_api_client import ToolsAPIClient  # noqa: E402
from util.scrapers.tools_api_dump import dump_endpoint  # noqa: E402


def run(client: ToolsAPIClient, *, use_cache: bool = True) -> int:
    out = (
        Path(__file__).resolve().parent.parent
        / 'autogenerated' / 'shops.py'
    )
    n = dump_endpoint(
        client, 'shops', str(out), 'SHOPS',
        use_cache=use_cache,
        docstring=(
            'Shops — keyed by shop id. soldItems is an array of item ids. '
            'API does NOT yet expose stock/price/currency per item; the '
            'wiki-scraped shops.py is still the source of truth for those.'
        ),
    )
    print(f'  [shops              ] {n:4d} entities → shops.py')
    return n


if __name__ == '__main__':
    raise SystemExit(0 if run(ToolsAPIClient()) else 1)
